/// Embeds the repository's shared schemas (`../schema`, without fixtures) into
/// `lib/config/shared_schemas.g.dart`, so the editor validates offline.
///
///   dart run tool/embed_schemas.dart          # rewrite the generated file
///   dart run tool/embed_schemas.dart --check  # exit 1 when it is stale
library;

import 'dart:io';

const String generatedPath = 'lib/config/shared_schemas.g.dart';

/// Every shared schema file by its path relative to the schema folder.
Map<String, String> readSharedSchemas(Directory schemaDirectory) {
  final Map<String, String> sources = <String, String>{};
  final List<File> files = schemaDirectory
      .listSync(recursive: true)
      .whereType<File>()
      .where((File file) => file.path.endsWith('.json'))
      .toList();
  for (final File file in files) {
    final String relative = file.path.substring(schemaDirectory.path.length + 1).replaceAll(r'\', '/');
    if (relative.startsWith('fixtures/')) continue;
    sources[relative] = file.readAsStringSync();
  }
  return sources;
}

String renderSharedSchemas(Map<String, String> sources) {
  final List<String> keys = sources.keys.toList()..sort();
  final StringBuffer out = StringBuffer()
    ..writeln('// GENERATED by tool/embed_schemas.dart from ../schema. Do not edit.')
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln()
    ..writeln('/// Shared schema sources by path relative to the repository schema folder.')
    ..writeln('const Map<String, String> sharedSchemaSources = <String, String>{');
  for (final String key in keys) {
    final String source = sources[key]!;
    if (source.contains("'''")) throw StateError("$key contains ''' and cannot be embedded");
    out
      ..writeln("  '$key': r'''")
      ..write(source)
      ..writeln("''',");
  }
  out.writeln('};');
  return out.toString();
}

void main(List<String> arguments) {
  final Directory schemaDirectory = Directory('../schema');
  if (!schemaDirectory.existsSync()) {
    stderr.writeln('Run from animus-web/; ../schema is missing.');
    exit(2);
  }
  final String rendered = renderSharedSchemas(readSharedSchemas(schemaDirectory));
  final File target = File(generatedPath);
  if (arguments.contains('--check')) {
    if (!target.existsSync() || target.readAsStringSync() != rendered) {
      stderr.writeln('$generatedPath is stale; run dart run tool/embed_schemas.dart');
      exit(1);
    }
    return;
  }
  target.parent.createSync(recursive: true);
  target.writeAsStringSync(rendered);
  stdout.writeln('Wrote $generatedPath');
}
